  if(patr != null) copy.patrimonio = patr;
  var serie = val(['kr-os-serie','ko-serie','ca-serie']);
  if(serie != null) copy.serie = serie;
  var local = val(['kr-os-local','ko-local','ca-local']);
  if(local != null) copy.local = local;
