  var html = (loc.items||[]).map(function(it){
    return '<button onclick="'+it.click+'"><i class="ph '+it.icon+'"></i>'+esc(it.label)+'</button>';
  }).join('');
  if(/chamado/i.test(menu.textContent||'') || menu.querySelectorAll('button').length !== (loc.items||[]).length){
    menu.innerHTML = html;
  }
